import{z as s,x as B,o as E,c as d,q as A,j as o,D as e,d as l,s as i,S as n,b as r}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"二次电子产额","description":"","frontmatter":{"title":"二次电子产额","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/euv-secondary-electron.md","filePath":"litho/euv-secondary-electron.md","lastUpdated":1791413859000}'),p={name:"litho/euv-secondary-electron.md"};function h(D,a,u,m,c,f){const t=B("Mermaid");return E(),d("div",null,[a[2]||(a[2]=A('<h1 id="二次电子产额" tabindex="-1">二次电子产额 <a class="header-anchor" href="#二次电子产额" aria-label="Permalink to &quot;二次电子产额&quot;">​</a></h1><div class="epigraph"><p>92 eV 的光子几乎不当场完成化学：电离之后是一串二次电子，产额与热化距离把空中像卷积成潜像核。</p><footer>—— 据 Naulleau 对 EUV 二次电子模糊、Kozawa 对电离产酸的公开论述整理</footer></div><p><a href="/litho/euv-underlayer">上一课</a>把底层写成黏附、隔离与界面二次电子的功能栈，并警告底层可以往胶里灌电子。缺口是把「二次电子」从一句接口变成产额：一次吸收生出多少电子、它们走多远、怎样变成酸或配体事件。本课钉二次电子产额与模糊。放气留给<a href="/litho/resist-outgassing">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DUV 的 PAG 可以靠光子直接光解。EUV 光子约 92 eV，远高于电离阈，能量先变成光电子与级联二次电子，再把能量交给 PAG 或锡氧配体。Kozawa 把 CAR 在 EUV 上的产酸写成电离路径：热化电子附着、酸从 PAG 释放，量子效率不再是「一个光子一颗酸」的 DUV 图像。Naulleau 把电子在凝聚态里走的那几纳米叫做二次电子模糊：它不随 \\(\\lambda/\\mathrm{NA}\\) 缩放。</p><p><span class="marginnote">「热化」就是二次电子一路碰撞把能量花光、慢到再也推不动分子的过程；它走过的直线距离叫热化距离，量级只有几纳米。这几纳米是光刻机再完美也消不掉的模糊底座，也是「电子模糊核不随 NA 缩放」的物理来源。</span></p><p>底层课已经指出：高 Z 底层会抬界面产额，灵敏度「免费」上升，模糊与随机一起改。缺口是产额本身——secondary electron yield——而不是再列一次底层功能。</p><h3 id="产额不是灵敏度的别名" tabindex="-1">产额不是灵敏度的别名 <a class="header-anchor" href="#产额不是灵敏度的别名" aria-label="Permalink to &quot;产额不是灵敏度的别名&quot;">​</a></h3><p>灵敏度是多少 \\(\\mathrm{mJ/cm^2}\\) 打到目标 CD。产额是每个被吸收光子（或每电子伏沉积能量）最终贡献多少化学事件。吸收截面、电子逃逸、淬灭、团簇离散都会插在中间。只报更敏，不知道是锡吸收高了、底层灌电子了，还是化学增益大了。</p><p><span class="marginnote">不要把二次电子模糊写成某一个全球纳米常数。公开论述给出的是纳米量级热化距离，随材料与密度变。本课钉机制，不编未校准的射程表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>紧凑模型：剂量 → 吸收 → 电子核卷积 → 酸或配体事件密度 → 显影。电子核与酸核要能分开标定：降 PEB 主要砍酸程；换底层、换高 Z 负载主要砍电子项。量测上，LER 频谱的中高频、孔的随机失效对剂量的曲线，用来拆核与泊松——<a href="/litho/euv-absorption-blur">吸收与模糊</a> 在光学课序里已经用过这套拆法，本课把它接到胶栈的产额语言上。</p><p>底层实验：同一胶、只换 underlayer 的二次电子产额，看 \\(E_0\\) 与侧壁。界面产额升高，底部事件变密，footing 或倒锥会走——与光学离焦同貌，先查栈。</p><p><span class="marginnote">可以把二次电子级联想成打台球：母球（光电子）撞开一串彩球，每颗彩球又去撞下一颗，碰撞途中顺手把 PAG「撞」出一颗酸。球桌的大小就是热化距离——桌子越大，图像糊得越厉害，产酸却可能越多。</span></p><h3 id="后课默认" tabindex="-1">后课默认 <a class="header-anchor" href="#后课默认" aria-label="Permalink to &quot;后课默认&quot;">​</a></h3><p>说到 EUV 潜像，默认事件由二次电子介导，而不是 DUV 式直接光解。说到模糊，默认电子核与酸核（若仍是 CAR）叠加。金属氧化物胶没有长程酸，核更接近电子与团簇。</p>',16)),(E(),o(n,null,{default:e(()=>[i(t,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20PH%5B%22EUV%20%E5%85%89%E5%AD%90%E5%90%B8%E6%94%B6%22%5D%20--%3E%20ION%5B%22%E7%94%B5%E7%A6%BB%20%2F%20%E5%85%89%E7%94%B5%E5%AD%90%22%5D%0A%20%20ION%20--%3E%20SE%5B%22%E4%BA%8C%E6%AC%A1%E7%94%B5%E5%AD%90%E7%BA%A7%E8%81%94%22%5D%0A%20%20SE%20--%3E%20Y%5B%22%E4%BA%A7%E9%A2%9D%3A%20%E4%BA%8B%E4%BB%B6%20%2F%20%E5%85%89%E5%AD%90%22%5D%0A%20%20UL%5B%22%E5%BA%95%E5%B1%82%E7%81%8C%E5%85%A5%E7%9A%84%E7%94%B5%E5%AD%90%22%5D%20--%3E%20Y%0A%20%20Y%20--%3E%20CHEM%5B%22PAG%20%E4%BA%A7%E9%85%B8%E6%88%96%E9%85%8D%E4%BD%93%E8%A7%A3%E7%A6%BB%22%5D%0A%20%20Y%20--%3E%20BLUR%5B%22%E4%BA%8C%E6%AC%A1%E7%94%B5%E5%AD%90%E6%A8%A1%E7%B3%8A%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[l("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"一次 92 eV 吸收可打出多个电子–空穴，电子在散射中降能，直到热化。热化距离给出空间核半径量级。产额取决于：材料电离截面、电子在膜里的逃逸与复合、受体（PAG、配体）的捕获截面。Kozawa 强调：电子附着路径让产酸效率对 PAG 分布和聚合物电子性质敏感，不是只对光学 \\(I(x)\\) 敏感。Naulleau 强调：核把 NILS 砍掉一截，随机体积也变，泊松 \\(N\\) 跟着变——模糊不是只糊边，也改缺陷统计。",-1)),(E(),o(n,null,{default:e(()=>[i(t,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20DUV%5B%22DUV%20%E5%85%89%E5%AD%90%206.4%20eV%22%5D%20--%3E%20DP%5B%22%E7%9B%B4%E6%8E%A5%E5%85%89%E8%A7%A3%20PAG%22%5D%0A%20%20DP%20--%3E%20A1%5B%22%E4%B8%80%E4%B8%AA%E5%85%89%E5%AD%90%E8%87%B3%E5%A4%9A%E4%B8%80%E9%A2%97%E9%85%B8%22%5D%0A%20%20EUV%5B%22EUV%20%E5%85%89%E5%AD%90%2092%20eV%22%5D%20--%3E%20PE%5B%22%E6%89%93%E5%87%BA%E5%85%89%E7%94%B5%E5%AD%90%22%5D%0A%20%20PE%20--%3E%20CAS%5B%22%E7%BA%A7%E8%81%94%E4%BA%8C%E6%AC%A1%E7%94%B5%E5%AD%90%22%5D%0A%20%20CAS%20--%3E%20A2%5B%22%E5%A4%9A%E9%A2%97%E9%85%B8%20%2B%20%E7%BA%B3%E7%B1%B3%E7%BA%A7%E6%A8%A1%E7%B3%8A%22%5D%0A%20%20A1%20--%3E%20IMG%5B%22%E6%BD%9C%E5%83%8F%3A%20%E8%83%BD%E9%87%8F%E5%88%86%E5%B8%83%E5%8F%98%E5%8C%96%E5%AD%A6%E4%BA%8B%E4%BB%B6%E5%88%86%E5%B8%83%22%5D%0A%20%20A2%20--%3E%20IMG%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=A('<p>这张图回答的是：同样一份剂量，DUV 与 EUV 到达化学的路径差在哪——DUV 近似一对一，EUV 经电离级联一对多，模糊就是这条路径的空间代价。</p><p>界面：底层产生的电子向上注入，胶底部有效产额升高，轴向不对称。这是底层课的机制在产额符号下的重写，不是新光学。</p><p><span class="marginnote">高产额看起来像免费光子，其实是把事件挪到电子射程里。射程与半节距抢同一纳米预算时，加吸收、加产额都会先糊后敏。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不编每光子产酸个数的「标准值」，不把某胶的实验室 G 值当节点规格。不重写完整 RLS 推导。下一课放气是真空卫生，与电子产额正交：产额再高，碳氢出气仍会污染多层膜。</p><p><span class="marginnote">初学者容易把「灵敏度提高」当成纯好消息。若灵敏度来自底层灌电子，模糊与随机一起变大，孔反而更容易缺失。所以实验要固定胶、只换底层，看 \\(E_0\\) 与侧壁怎么跟着走，才能判断这笔交易划不划算。</span></p><p>光学 flare 与电子核不要混：flare 改空中像的远程台基；电子核是吸收点附近的纳米卷积。调焦补不了后者。锡氧胶没有长程酸，产额仍在：电子打断配体的效率随团簇与底层变，换胶族等于换 \\(Y\\)，紧凑模型要重拟合核，不能只改剂量。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>EUV 化学事件由二次电子介导；产额是事件/吸收，不是灵敏度的别名。</li><li>Kozawa：电离产酸；Naulleau：电子模糊核不随 NA 缩放。</li><li>底层灌电子改界面产额与侧壁，先查栈再怪照明。</li><li>核砍 NILS，也改随机体积；加产额不是免费分辨率。</li><li>换胶族等于换产额 \\(Y\\)；紧凑模型要重拟合核。</li><li>调焦补不了电子核；flare 是远程台基，不要与核混。</li><li>出处：Kozawa 对 EUV 电离产酸的论述；Naulleau 对二次电子模糊的公开讨论。</li></ul>',9))])}const _=s(p,[["render",h]]);export{P as __pageData,_ as default};
